import * as THREE from 'three/webgpu';
import { texture, uv, vec2, mix, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasW = 512;
  const atlasH = 320;

  const aspect = rect.w / rect.h;
  const width = 1.6;
  const height = width / aspect;

  const geometry = new THREE.PlaneGeometry(width, height, 1, 1);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  const offsetX = rect.x / atlasW;
  const offsetY = 1.0 - (rect.y + rect.h) / atlasH;
  const scaleX = rect.w / atlasW;
  const scaleY = rect.h / atlasH;

  const uvOffset = uniform(new THREE.Vector2(offsetX, offsetY));
  const uvScale = uniform(new THREE.Vector2(scaleX, scaleY));

  const atlasUV = uv().mul(uvScale).add(uvOffset);
  const mapNode = texture(map, atlasUV);

  const material = new THREE.MeshBasicNodeMaterial();
  material.mapNode = mapNode;
  material.colorNode = mapNode;
  material.transparent = false;
  material.toneMapped = false;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'hub-collection-card-0-collection-card-3';

  const node = new THREE.Group();
  node.add(mesh);

  node.position.set(3.2, -0.3, 0);
  node.rotation.set(0, 0, 0);
  node.scale.set(1, 1, 1);

  node.onBeforeRender = (renderer, scene, camera) => {
    node.quaternion.copy(camera.quaternion);
  };

  node.userData.handlers = {};

  node.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
  };

  return node;
}
